<?php defined('ABSPATH')||exit;require_once __DIR__.'/data.php';$data=\RadmanLibrary\Designs\StickyCards\data(); ?>
<section class="rdl-spl" data-rdl-spl><div class="rdl-spl__row"><div class="rdl-spl__side"><div class="rdl-spl__rail" aria-hidden="true"><span data-rdl-spl-dot></span></div><header class="rdl-spl__hdr" dir="rtl"><h1><?php echo esc_html($data['title']); ?></h1><p><?php echo esc_html($data['desc']); ?></p><?php $id=(int)$data['symbol'];if(\RadmanCT\PageTitle\attachment_allowed($id))echo wp_get_attachment_image($id,'full',false,['alt'=>'','width'=>56,'height'=>56,'class'=>'rdl-spl__symbol']); ?></header></div><div class="rdl-spl__list">
<?php foreach($data['items'] as $item): ?><article class="rdl-spl__card" dir="rtl"><figure><?php $id=(int)$item['image'];if(\RadmanCT\PageTitle\attachment_allowed($id)&&wp_attachment_is_image($id))echo wp_get_attachment_image($id,'large',false,['loading'=>'lazy','sizes'=>'(max-width:767px) 100vw,50vw']); ?></figure><h2><?php echo esc_html($item['title']); ?></h2><p><?php echo esc_html($item['desc']); ?></p><ul><?php foreach($item['items'] as $text): ?><li><span aria-hidden="true">+</span> <?php echo esc_html($text); ?></li><?php endforeach; ?></ul></article><?php endforeach; ?>
</div></div></section>
